mapper.select:
SELECT * FROM audit_log WHERE tenant_id = #{tenantId}
AND user_id = #{userId}

    AND LOCATE(LOWER(#{query}), LOWER(CONCAT_WS(' ', action, resource_type, resource_id,
        username, user_id, message, status, client_ip))) > 0




            AND (created_at < #{cursor.time} OR (created_at = #{cursor.time}
                AND id < CAST(#{cursor.id} AS UNSIGNED)) OR created_at IS NULL)

        AND created_at IS NULL AND id < CAST(#{cursor.id} AS UNSIGNED)


ORDER BY created_at DESC, id DESC LIMIT #{limit}
